#[allow(dead_code)] fn commit_nfa_cast_results<'a>(category: CategoryId, min_bp: u8, mut results: Vec<(AnyTerm, usize, f64)>, pos: &mut usize, ) -> ParseStep { /* Sort by weight ascending (best first) */ results.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal)); let (best, best_pos, _best_weight) = results.remove(0); *pos = best_pos; /* Spill remaining alternatives to NFA_PREFIX_SPILL */ match category { CategoryId::Int => { NFA_PREFIX_SPILL_INT.with(|cell| { let mut spill = cell.take(); for (term, end_pos, weight) in results { if let AnyTerm::Int(v) = term { spill.push((*v, end_pos, weight)); } } spill.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal)); cell.set(spill); }); ParseStep::ContinueInfix { cat: CategoryId::Int, lhs: best, bp: min_bp } }, CategoryId::Float => { NFA_PREFIX_SPILL_FLOAT.with(|cell| { let mut spill = cell.take(); for (term, end_pos, weight) in results { if let AnyTerm::Float(v) = term { spill.push((*v, end_pos, weight)); } } spill.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal)); cell.set(spill); }); ParseStep::ContinueInfix { cat: CategoryId::Float, lhs: best, bp: min_bp } }, CategoryId::Bool => { NFA_PREFIX_SPILL_BOOL.with(|cell| { let mut spill = cell.take(); for (term, end_pos, weight) in results { if let AnyTerm::Bool(v) = term { spill.push((*v, end_pos, weight)); } } spill.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal)); cell.set(spill); }); ParseStep::ContinueInfix { cat: CategoryId::Bool, lhs: best, bp: min_bp } }, CategoryId::Str => { NFA_PREFIX_SPILL_STR.with(|cell| { let mut spill = cell.take(); for (term, end_pos, weight) in results { if let AnyTerm::Str(v) = term { spill.push((*v, end_pos, weight)); } } spill.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal)); cell.set(spill); }); ParseStep::ContinueInfix { cat: CategoryId::Str, lhs: best, bp: min_bp } }, } }
